// Simulación de la idea de las particiones (no es Kafka: el hash y el reparto son simples).
const N = 3;                                         // particiones del tema
const particiones = Array.from({ length: N }, () => []);

function hash(clave) {                               // FNV-1a de 32 bits
  let h = 0x811c9dc5;
  for (const c of clave) { h ^= c.charCodeAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h;
}
const enviar = (clave, evento) => particiones[hash(clave) % N].push(`${clave}:${evento}`);

// los eventos de cinco pedidos llegan entremezclados, pero en orden dentro de cada pedido
const pasos = ['creado', 'pagado', 'despachado'];
for (const paso of pasos)
  for (const pedido of ['P-101', 'P-102', 'P-103', 'P-104', 'P-105']) enviar(pedido, paso);

particiones.forEach((p, i) => console.log(`partición ${i}: ${p.join('  ')}`));

// un grupo de consumidores: cada partición la lee un solo consumidor, en orden
function reparto(consumidores) {
  const mapa = {};
  for (let p = 0; p < N; p++) (mapa[`c${p % consumidores + 1}`] ??= []).push(p);
  return mapa;
}
for (const k of [1, 2, 3, 5])
  console.log(`${k} consumidor(es) en el grupo -> ${JSON.stringify(reparto(k))}`);
